function inlineSprite(imageId: number): string {//Converts the image to an inline sprite ID. Didn't work, but in theory, it can still work for smaller pictures.
    const b0 = imageId & 0xFF;
    const b1 = (imageId >> 8) & 0xFF;
    const b2 = (imageId >> 16) & 0xFF;
    const b3 = (imageId >> 24) & 0xFF;
  
    return `{INLINE_SPRITE}{${b0}}{${b1}}{${b2}}{${b3}}`;
  }

